WITH flattened_attrs AS (SELECT id, customer_id, created_at, items, ship_to, EXISTS(coupon_codes, c -> c LIKE 'W%') AS has_welcome_code, SIZE(FILTER(items, i -> i.qty >= 3)) AS bulk_lines, ARRAY_MAX(TRANSFORM(items, i -> i.price)) AS max_item_price FROM carts WHERE customer_id = 25) SELECT customer_id, ROUND(AVG(bulk_lines), 2) AS avg_bulk_lines, COUNT(*) AS row_count, PERCENTILE_APPROX(bulk_lines, 0.5) AS bulk_lines_p50 FROM flattened_attrs GROUP BY customer_id ORDER BY bulk_lines_p50 NULLS FIRST;
